// Language JSON File Location
var language = localStorage.getItem('language');
// Default Language
var default_lang = 'pt-br';

// Translate
var translate = null;

// Set Selected Language
function setLanguage(lang) {
    localStorage.setItem('language', lang);
    language = localStorage.getItem('language');

    var data = {
        "language": language
    };

    //console.log(data);

    $.ajax({
        url: '/api/v1/language',
        type: "POST",
        data: JSON.stringify(data),
        dataType: "json",
        contentType: "application/json;charset=utf-8"
    });

    // Run Multi Language Plugin
    getLanguage()
}

function saveTranslate(language, json_translate) {
    let json = JSON.stringify(json_translate);
    //console.log(json);

    let encodedTransltate = btoa(json);
    //console.log(encodedTransltate);

    localStorage.setItem(language, encodedTransltate);
}

function getTranslate(language) {
    let json_encoded = localStorage.getItem(language);
    //console.log(json_encoded);

    if (json_encoded != null) {
        let json_decode = atob(json_encoded);
        //console.log(json_decode);

        translate = JSON.parse(json_decode);
    } else {
        translate = null;
    }
}

function processTranslate() {
    // add selected language class to the body tag
    $('body').attr('class', language);
    // Loop through message in data
    $.each(translate, function (index, val) {
        (index === 'head') ? $(document).attr("title", val['title']) : false;
        $(index).children().each(function () {
            $(this).text(val[$(this).attr('key')]);

            if ($(this).attr('type') == 'hidden') {
                $(this).val(val[$(this).attr('key')]);
            }
        });
    });
}

// Run Multi Language Plugin
function getLanguage() {
    // Language on user preference
    (language == null) ? setLanguage(default_lang) : false;
    // Load data of selected language

    getTranslate(language);

    if (translate == null) {
        var data = {
            "language": language
        };

        $.ajax({
            url: '/api/v1/translate',
            type: "POST",
            data: JSON.stringify(data),
            dataType: "json",
            contentType: "application/json;charset=utf-8",
            success: function (lang) {
                translate = lang;
                processTranslate();

                saveTranslate(language, lang);
            }
        });


    } else {
        processTranslate();
    }
}

// Auto Loader
$(document).ready(function () {
    if (language != null && language !== default_lang)
        getLanguage(language);
});
